package main
import("debug/dwarf";"debug/elf";"encoding/json";"os";"strings")
func main(){results:=map[string]map[string]int64{};for _,path:=range os.Args[1:]{f,e:=elf.Open(path);if e!=nil{panic(e)};d,e:=f.DWARF();if e!=nil{panic(e)};r:=d.Reader();sizes:=map[string]int64{};for{entry,e:=r.Next();if e!=nil{panic(e)};if entry==nil{break};if entry.Tag!=dwarf.TagStructType{continue};name,_:=entry.Val(dwarf.AttrName).(string);if strings.HasPrefix(name,"github.com/microsoft/typescript-go/internal/") && (strings.HasSuffix(name,"/ast.Symbol")||strings.HasSuffix(name,"/ast.SymbolAllocator")||strings.HasSuffix(name,"/checker.Checker")||strings.HasSuffix(name,"/binder.Binder")){typ,e:=d.Type(entry.Offset);if e!=nil{panic(e)};sizes[name]=typ.Size()}};results[path]=sizes;f.Close()};if e:=json.NewEncoder(os.Stdout).Encode(results);e!=nil{panic(e)}}
